-- Phase 9: organization/branch administration, operational reports, exports and audit viewing.
create table public.organizations(id uuid primary key default gen_random_uuid(),legal_name text not null,tagline text,registration_no text,pan_vat text,timezone text not null default'Asia/Kathmandu',fiscal_year text,currency text not null default'NPR',address text,phone text,email citext,updated_by uuid not null references public.staff_profiles(id),updated_at timestamptz not null default now());
create table public.branches(id uuid primary key default gen_random_uuid(),branch_code text not null unique,name text not null,address text,phone text,cost_centre text not null unique,manager_id uuid references public.staff_profiles(id),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.report_definitions(id uuid primary key default gen_random_uuid(),report_key text not null unique,name text not null,category text not null,description text,required_permission text not null,source_view text not null,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.report_exports(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.report_definitions(id),requested_by uuid not null references public.staff_profiles(id),format text not null check(format in('CSV','XLSX','PDF')),filters jsonb not null default'{}',status text not null default'QUEUED'check(status in('QUEUED','PROCESSING','COMPLETED','FAILED','EXPIRED')),storage_path text,error_message text,created_at timestamptz not null default now(),completed_at timestamptz);
insert into public.permissions(role,permission_name,enabled)select role,permission_name,true from(values('ADMIN'::public.staff_role),('DIRECTOR'))r(role)cross join(values('reports.view'),('reports.export'),('branches.manage'),('rbac.manage'),('audit.view'))p(permission_name)on conflict(role,permission_name)do update set enabled=true;
insert into public.permissions(role,permission_name,enabled)select role,'reports.view',true from(values('ACCOUNTANT'::public.staff_role),('FINANCE'),('SENIOR_COUNSELLOR'))r(role)on conflict(role,permission_name)do update set enabled=true;
insert into public.report_definitions(report_key,name,category,description,required_permission,source_view)values('lead_pipeline','Lead Pipeline','Admissions','Lead stage, ownership and conversion performance','reports.view','report_lead_pipeline'),('application_pipeline','Application Pipeline','Admissions','University application stages and deadlines','reports.view','report_application_pipeline'),('finance_summary','Finance Summary','Finance','Invoices, receipts and outstanding balances','finance.view','report_finance_summary'),('staff_attendance','Staff Attendance','HR','Attendance, lateness and leave summary','hr.view','report_staff_attendance')on conflict(report_key)do nothing;
alter table public.organizations enable row level security;alter table public.branches enable row level security;alter table public.report_definitions enable row level security;alter table public.report_exports enable row level security;
create policy organization_staff_read on public.organizations for select to authenticated using(public.is_active_staff());create policy organization_admin_write on public.organizations for all to authenticated using(public.has_permission('admin.manage'))with check(public.has_permission('admin.manage'));
create policy branches_staff_read on public.branches for select to authenticated using(public.is_active_staff());create policy branches_admin_write on public.branches for all to authenticated using(public.has_permission('branches.manage'))with check(public.has_permission('branches.manage'));
create policy report_catalog_read on public.report_definitions for select to authenticated using(public.has_permission(required_permission));create policy own_report_exports on public.report_exports for select to authenticated using(requested_by=auth.uid()or public.has_permission('reports.export'));
create or replace view public.report_lead_pipeline with(security_invoker=true)as select stage,priority,count(*)record_count,count(*)filter(where created_at>=date_trunc('month',now()))month_count from public.leads group by stage,priority;
create or replace view public.report_application_pipeline with(security_invoker=true)as select stage,country,count(*)record_count,count(*)filter(where deadline<current_date)overdue_count from public.university_applications group by stage,country;
create or replace view public.report_finance_summary with(security_invoker=true)as select status,count(*)invoice_count,coalesce(sum(grand_total),0)invoiced_total,coalesce(sum((select coalesce(sum(amount),0)from public.finance_receipts r where r.invoice_id=i.id)),0)received_total from public.finance_invoices i group by status;
create or replace view public.report_staff_attendance with(security_invoker=true)as select attendance_date,status,count(*)record_count,coalesce(sum(late_minutes),0)late_minutes from public.hr_attendance group by attendance_date,status;
create or replace function public.management_dashboard_summary()returns jsonb language plpgsql stable security definer set search_path=public as $$declare result jsonb;begin if not public.is_active_staff()then raise exception'Insufficient permission';end if;select jsonb_build_object('students',(select count(*)from students),'leads',(select count(*)from leads where stage<>'CONVERTED'),'counselling',(select count(*)from counselling_records),'offers',(select count(*)from university_applications where stage in('CONDITIONAL_OFFER','UNCONDITIONAL_OFFER','CAS_ISSUED','VISA_LODGED','VISA_APPROVED','ENROLLED')),'visa_ratio',(select case when count(*)filter(where visa_status in('APPROVED','REJECTED'))=0 then 0 else round(100.0*count(*)filter(where visa_status='APPROVED')/count(*)filter(where visa_status in('APPROVED','REJECTED')),1)end from visa_tracking),'month_revenue',(select coalesce(sum(amount),0)from finance_receipts where received_at>=date_trunc('month',now())),'pending_tasks',(select count(*)from case_tasks where status<>'COMPLETED'))into result;return result;end$$;
create or replace function public.save_organization(payload jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare oid uuid;begin if not public.has_permission('admin.manage')then raise exception'Insufficient permission';end if;select id into oid from organizations order by updated_at desc limit 1;if oid is null then insert into organizations(legal_name,tagline,registration_no,pan_vat,timezone,fiscal_year,currency,address,phone,email,updated_by)values(payload->>'legal_name',payload->>'tagline',payload->>'registration_no',payload->>'pan_vat',payload->>'timezone',payload->>'fiscal_year',payload->>'currency',payload->>'address',payload->>'phone',(payload->>'email')::citext,auth.uid())returning id into oid;else update organizations set legal_name=payload->>'legal_name',tagline=payload->>'tagline',registration_no=payload->>'registration_no',pan_vat=payload->>'pan_vat',timezone=payload->>'timezone',fiscal_year=payload->>'fiscal_year',currency=payload->>'currency',address=payload->>'address',phone=payload->>'phone',email=(payload->>'email')::citext,updated_by=auth.uid(),updated_at=now()where id=oid;end if;insert into audit_logs(user_id,action,module,metadata)values(auth.uid(),'ORGANIZATION_UPDATED','administration',jsonb_build_object('organization_id',oid));return oid;end$$;
create or replace function public.request_report_export(report_key text,export_format text,report_filters jsonb default'{}')returns uuid language plpgsql security definer set search_path=public as $$declare rid uuid;eid uuid;perm text;begin select id,required_permission into rid,perm from report_definitions where report_definitions.report_key=request_report_export.report_key and is_active;if rid is null or not public.has_permission(perm)then raise exception'Report unavailable';end if;if export_format not in('CSV','XLSX','PDF')then raise exception'Unsupported format';end if;insert into report_exports(report_id,requested_by,format,filters)values(rid,auth.uid(),export_format,report_filters)returning id into eid;insert into audit_logs(user_id,action,module,metadata)values(auth.uid(),'REPORT_EXPORT_REQUESTED','reports',jsonb_build_object('report_key',report_key,'format',export_format));return eid;end$$;
revoke all on function public.management_dashboard_summary(),public.save_organization(jsonb),public.request_report_export(text,text,jsonb)from public;grant execute on function public.management_dashboard_summary(),public.save_organization(jsonb),public.request_report_export(text,text,jsonb)to authenticated;
